function buildCOATree(data){
    const map={}, roots=[];
    data.forEach(n=>{ map[n.id]=n; n.children=[]; });
    data.forEach(n=>{ if(n.parentId && map[n.parentId]){ map[n.parentId].children.push(n); } else { roots.push(n); } });
    return roots;
}
